#!/usr/bin/env bash
# apply_reorganisation.sh -- bring an older checkout of this repository into line with the
# file moves and deletions of the repository check of 31 October 2026.
#
# Created 31 October 2026 (repository check). Last altered 31 October 2026 (every
# removal now checks exact content: nothing that differs from the known file is deleted;
# later the same day the paths the new wheels left when they moved -- first out of the
# package into their intake items' staged/ folders, then, by the owner's decision, back into
# the package provisionally -- each removed only when it is an empty file or a version this
# check delivered there). Last altered 1 November 2026 (Phase 186: Rule30_GLM_Study and
# glm_wheels_bundle absorbed ahead of their Lean build and filed in source_material/done/ -- their
# moves now end in done/, a ToDo/ copy left by the previous delivery is moved or removed when it
# is byte for byte the done/ file, the bundle's done/ files are no longer listed for removal,
# and an empty file at a move's new place, a retracted placeholder, is replaced by the old copy).
#
# Why: the files changed in this round were delivered as files, and a delivery of files
# cannot express a move or a deletion. Run this once from the repository root after
# copying the delivered files over your checkout. It is idempotent and only ever:
#   * moves a file from its old place to its new one when the new place is empty;
#   * removes an old copy when the new place is filled AND the old copy is byte for byte
#     either the new file or the file as it stood before the reorganisation (its SHA-256
#     is listed below); any other old copy is kept and reported as a conflict;
#   * removes a file this round deleted only when it is byte for byte the empty placeholder
#     that was deleted (SHA-256 listed below); a file with any other content -- for
#     example a recovered Lean file -- is kept and reported.
# Nothing outside the listed paths is touched. Use --dry-run to see what it would do.
# Exit status 0 when every path was settled; 1 when a path was missing or a conflict was
# kept for you to resolve by hand.
set -u
DRY=0; [ "${1:-}" = "--dry-run" ] && DRY=1
cd "$(dirname "$0")/.." || exit 1
if command -v sha256sum >/dev/null 2>&1; then hash_of() { sha256sum -- "$1" | cut -d" " -f1; }
elif command -v shasum >/dev/null 2>&1; then hash_of() { shasum -a 256 -- "$1" | cut -d" " -f1; }
else echo "need sha256sum or shasum to compare contents; nothing done"; exit 1; fi
moved=0; removed=0; already=0; missing=0; conflicts=0
mv_one() {  # old new sha256-of-old-before-the-reorganisation
  # An empty file at the new place is a retracted placeholder (a delivery of files retracts a file by
  # delivering it empty): a non-empty old copy is moved over it (1 November 2026).
  if [ -e "$2" ] && [ ! -s "$2" ] && [ -s "$1" ]; then
    if [ $DRY = 1 ]; then echo "move over empty placeholder: $1 -> $2"; else mv -- "$1" "$2"; fi; moved=$((moved+1))
  elif [ -e "$2" ]; then
    if [ -e "$1" ]; then
      if cmp -s -- "$1" "$2" || [ "$(hash_of "$1")" = "$3" ]; then
        if [ $DRY = 1 ]; then echo "remove old copy: $1"; else rm -f -- "$1"; fi; removed=$((removed+1))
      else
        conflicts=$((conflicts+1)); echo "conflict, both kept (the old copy differs from the new file and from the known old one): $1 vs $2"
      fi
    else already=$((already+1)); fi
  elif [ -e "$1" ]; then
    if [ $DRY = 1 ]; then echo "move: $1 -> $2"; else mkdir -p -- "$(dirname -- "$2")" && mv -- "$1" "$2"; fi; moved=$((moved+1))
  else missing=$((missing+1)); echo "neither old nor new present: $1 -> $2"; fi
}
rm_one() {  # path sha256-of-the-placeholder-that-was-deleted
  if [ ! -e "$1" ]; then already=$((already+1))
  elif [ "$(hash_of "$1")" = "$2" ]; then
    if [ $DRY = 1 ]; then echo "delete placeholder: $1"; else rm -f -- "$1"; fi; removed=$((removed+1))
  else
    conflicts=$((conflicts+1)); echo "kept (not the deleted placeholder -- a recovered file? see studies/_lean_files_needed.md): $1"
  fi
}

