# ---- 17 paths the new wheels left (the wheels staged in their intake items, then installed back in
# ---- src/glm_universal/ provisionally, by the owner's decision).  Until 1 November 2026 this list also
# ---- held the 14 files of source_material/done/glm_wheels_bundle/ (the bundle was briefly filed in done/
# ---- and then back in ToDo/); since the bundle was absorbed ahead of its build and filed in done/ on
# ---- 1 November 2026 they are its live files, and are no longer listed. ----
# A delivery of files may still carry these old paths -- as the version delivered earlier or as an
# empty file standing for a retracted one. Each is removed only when its bytes are one of the
# versions listed (SHA-256; the first is the empty file); any other content is kept and reported.
# The live files are in src/glm_universal/wheels/ and src/glm_universal/tests/ and are delivered there.
rm_known() {  # path sha256 [sha256 ...]
  p="$1"; shift
  if [ ! -e "$p" ]; then already=$((already+1)); return; fi
  h="$(hash_of "$p")"
  for k in "$@"; do
    if [ "$h" = "$k" ]; then
      if [ $DRY = 1 ]; then echo "remove superseded copy: $p"; else rm -f -- "$p"; fi; removed=$((removed+1)); return
    fi
  done
  conflicts=$((conflicts+1)); echo "kept (not a version this check delivered at this path): $p"
}
